namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Code { get; set; } = "";
    public string Description { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public string Title { get; set; } = "";
    public string Bio { get; set; } = "";
    public string Email { get; set; } = "";
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Location { get; set; } = "";
    public int DepartmentId { get; set; }
    public Department Department { get; set; } = null!;
    public int InstructorId { get; set; }
    public Instructor Instructor { get; set; } = null!;
    public bool IsFeatured { get; set; }
    public int MaxEnrollment { get; set; }
    public int CurrentEnrollment { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    [StringLength(20)]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? search, int? departmentId);
    Course? GetCourse(int id);
    List<Course> GetFeaturedCourses();
    bool SubmitEnrollmentRequest(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Explore the foundations and frontiers of computing, from algorithms and data structures to artificial intelligence and software engineering." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Develop analytical and quantitative reasoning skills through the study of pure and applied mathematics." },
            new() { Id = 3, Name = "English", Code = "ENG", Description = "Study literature, writing, and rhetoric to sharpen critical thinking and communication skills." },
            new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Investigate the fundamental laws governing matter, energy, and the universe through theory and experimentation." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor", Bio = "Dr. Chen has over 20 years of experience in computer science education and research. She specializes in algorithms and machine learning, and has published more than 80 peer-reviewed papers.", Email = "achen@university.edu" },
            new() { Id = 2, Name = "Dr. Marcus Rivera", Title = "Associate Professor", Bio = "Dr. Rivera focuses on software engineering and distributed systems. He spent a decade in industry at major tech companies before joining academia.", Email = "mrivera@university.edu" },
            new() { Id = 3, Name = "Dr. Sarah Okafor", Title = "Professor", Bio = "Dr. Okafor is an award-winning mathematician whose research spans topology and abstract algebra. She has mentored dozens of graduate students.", Email = "sokafor@university.edu" },
            new() { Id = 4, Name = "Dr. James Whitfield", Title = "Assistant Professor", Bio = "Dr. Whitfield brings a fresh perspective to applied mathematics with research in numerical analysis and mathematical modeling.", Email = "jwhitfield@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Parker", Title = "Professor", Bio = "Dr. Parker is a renowned literary scholar specializing in 19th-century American literature and contemporary fiction. She has authored three books.", Email = "eparker@university.edu" },
            new() { Id = 6, Name = "Dr. David Kim", Title = "Associate Professor", Bio = "Dr. Kim teaches creative and technical writing. His essays and short stories have appeared in numerous literary journals.", Email = "dkim@university.edu" },
            new() { Id = 7, Name = "Dr. Maria Santos", Title = "Professor", Bio = "Dr. Santos is a leading researcher in quantum mechanics and condensed matter physics with over 100 publications.", Email = "msantos@university.edu" },
            new() { Id = 8, Name = "Dr. Robert Liu", Title = "Associate Professor", Bio = "Dr. Liu specializes in astrophysics and cosmology. He is an engaging lecturer known for making complex physics accessible to all students.", Email = "rliu@university.edu" }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "A broad introduction to computer science covering computational thinking, basic programming in Python, data representation, and an overview of major areas in the field.", Credits = 3, Schedule = "MWF 10:00\u201310:50 AM", Location = "Tech Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Analyze algorithm efficiency using Big-O notation and explore sorting and searching techniques.", Credits = 4, Schedule = "TTh 1:00\u20132:15 PM", Location = "Tech Hall 305", DepartmentId = 1, InstructorId = 1, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 310", Title = "Software Engineering", Description = "Learn modern software development methodologies including Agile and DevOps. Cover requirements analysis, system design, testing strategies, and project management.", Credits = 3, Schedule = "MWF 2:00\u20132:50 PM", Location = "Tech Hall 110", DepartmentId = 1, InstructorId = 2, IsFeatured = false, MaxEnrollment = 45, CurrentEnrollment = 40 },
            new() { Id = 4, Code = "CS 450", Title = "Artificial Intelligence", Description = "Explore the principles and techniques of artificial intelligence including search algorithms, knowledge representation, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "TTh 10:00\u201311:15 AM", Location = "Tech Hall 405", DepartmentId = 1, InstructorId = 2, IsFeatured = true, MaxEnrollment = 40, CurrentEnrollment = 38 },

            // Mathematics
            new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "An introduction to differential calculus covering limits, continuity, derivatives, and their applications to real-world problems in science and engineering.", Credits = 4, Schedule = "MWF 9:00\u20139:50 AM", Location = "Science Center 101", DepartmentId = 2, InstructorId = 3, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 6, Code = "MATH 102", Title = "Calculus II", Description = "Continuation of Calculus I covering integration techniques, sequences, series, parametric equations, and polar coordinates.", Credits = 4, Schedule = "MWF 11:00\u201311:50 AM", Location = "Science Center 101", DepartmentId = 2, InstructorId = 3, IsFeatured = false, MaxEnrollment = 120, CurrentEnrollment = 95 },
            new() { Id = 7, Code = "MATH 240", Title = "Linear Algebra", Description = "Study vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors with applications in data science and engineering.", Credits = 3, Schedule = "TTh 2:30\u20133:45 PM", Location = "Science Center 203", DepartmentId = 2, InstructorId = 4, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 42 },
            new() { Id = 8, Code = "MATH 350", Title = "Probability and Statistics", Description = "Introduction to probability theory, random variables, distributions, hypothesis testing, and regression analysis with real-world data sets.", Credits = 3, Schedule = "MWF 1:00\u20131:50 PM", Location = "Science Center 305", DepartmentId = 2, InstructorId = 4, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 48 },

            // English
            new() { Id = 9, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop foundational writing skills through essay composition, argumentation, research methods, and rhetorical analysis of diverse texts.", Credits = 3, Schedule = "MWF 10:00\u201310:50 AM", Location = "Humanities 102", DepartmentId = 3, InstructorId = 6, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 10, Code = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, examining major works, movements, and cultural contexts.", Credits = 3, Schedule = "TTh 11:00 AM\u201312:15 PM", Location = "Humanities 210", DepartmentId = 3, InstructorId = 5, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 30 },
            new() { Id = 11, Code = "ENG 315", Title = "Creative Writing Workshop", Description = "An intensive workshop in fiction and poetry writing. Students produce original works, participate in peer critique sessions, and study published authors' craft.", Credits = 3, Schedule = "W 3:00\u20135:30 PM", Location = "Humanities 105", DepartmentId = 3, InstructorId = 6, IsFeatured = true, MaxEnrollment = 18, CurrentEnrollment = 16 },

            // Physics
            new() { Id = 12, Code = "PHYS 101", Title = "General Physics I", Description = "Introduction to classical mechanics covering kinematics, Newton's laws, energy, momentum, rotational motion, and gravitation with laboratory exercises.", Credits = 4, Schedule = "MWF 8:00\u20138:50 AM + Lab Th 2:00\u20134:00 PM", Location = "Physics Building 101", DepartmentId = 4, InstructorId = 7, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
            new() { Id = 13, Code = "PHYS 102", Title = "General Physics II", Description = "Continuation covering electricity, magnetism, optics, and modern physics topics including relativity and quantum phenomena.", Credits = 4, Schedule = "MWF 9:00\u20139:50 AM + Lab T 2:00\u20134:00 PM", Location = "Physics Building 101", DepartmentId = 4, InstructorId = 7, IsFeatured = false, MaxEnrollment = 70, CurrentEnrollment = 52 },
            new() { Id = 14, Code = "PHYS 330", Title = "Quantum Mechanics", Description = "Formal introduction to quantum mechanics including wave functions, the Schr\u00f6dinger equation, operators, angular momentum, and applications to atomic systems.", Credits = 3, Schedule = "TTh 10:00\u201311:15 AM", Location = "Physics Building 301", DepartmentId = 4, InstructorId = 7, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 22 },
            new() { Id = 15, Code = "PHYS 410", Title = "Astrophysics", Description = "Study stellar structure and evolution, galaxies, cosmology, and the physics of the interstellar medium. Includes observational projects using the campus telescope.", Credits = 3, Schedule = "TTh 3:00\u20134:15 PM", Location = "Observatory 100", DepartmentId = 4, InstructorId = 8, IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 18 }
        };

        // Link navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) => true;
}

