            new() { Id = 13, Code = "PHYS 102", Title = "General Physics II", Description = "Continuation covering electricity, magnetism, optics, and modern physics topics including relativity and quantum phenomena.", Credits = 4, Schedule = "MWF 9:00\u20139:50 AM + Lab T 2:00\u20134:00 PM", Location = "Physics Building 101", DepartmentId = 4, InstructorId = 7, IsFeatured = false, MaxEnrollment = 70, CurrentEnrollment = 52 },
            new() { Id = 14, Code = "PHYS 330", Title = "Quantum Mechanics", Description = "Formal introduction to quantum mechanics including wave functions, the Schr\u00f6dinger equation, operators, angular momentum, and applications to atomic systems.", Credits = 3, Schedule = "TTh 10:00\u201311:15 AM", Location = "Physics Building 301", DepartmentId = 4, InstructorId = 7, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 22 },
