.form-floating > .form-control-plaintext:focus::placeholder, .form-floating > .form-control:focus::placeholder {
    text-align: start;
}

/* Course Catalog Custom Styles */
.hero-section {
    background: linear-gradient(135deg, #1b6ec2 0%, #1a3a5c 100%);
    color: #fff;
    padding: 3rem 2rem;
    border-radius: 0.5rem;
    margin-top: 0.5rem;
}

.hero-section .btn-primary {
    background-color: #fff;
    color: #1b6ec2;
    border-color: #fff;
    font-weight: 600;
}

.hero-section .btn-primary:hover {
    background-color: #e2e6ea;
    color: #1a3a5c;
}

.course-card, .department-card {
    transition: box-shadow 0.2s ease-in-out;
    border: 1px solid #dee2e6;
}

.course-card:hover, .department-card:hover {
    box-shadow: 0 0.25rem 0.75rem rgba(0, 0, 0, 0.15);
}

.card-footer {
    border-top: none;
}

.table-dark th {
    font-weight: 600;
}

